def _get_var_values(self, vars_to_load, attr, solution_number):
    """Return parallel lists of (pyomo vars, values) for the requested attr.

    If ``vars_to_load`` is None, all variables are returned; otherwise only
    the requested subset.  ``solution_number`` selects the Gurobi solution
    pool entry (0 is the incumbent).
    """
    if solution_number != 0:
        if (
            self._solver_model.getAttr('NumIntVars') == 0
            and self._solver_model.getAttr('NumBinVars') == 0
        ):
            raise ValueError(
                'Cannot obtain suboptimal solutions for a continuous model'
            )
        original_solution_number = self._solver_model.getParamInfo(
            'SolutionNumber'
        )[2]
        self._solver_model.setParam('SolutionNumber', solution_number)
    try:
        if vars_to_load is None:
            pyomo_vars, gvars = map(list, zip(*self._var_pair_iter()))
        else:
            var_map = self._get_var_map()
            pyomo_vars = list(vars_to_load)
            gvars = [var_map[i] for i in pyomo_vars]
        vals = self._solver_model.getAttr(attr, gvars)
    finally:
        if solution_number != 0:
            self._solver_model.setParam(
                'SolutionNumber', original_solution_number
            )
    return pyomo_vars, vals

def load_vars(
    self, vars_to_load: Optional[Sequence[VarData]] = None, solution_id=0
) -> None:
    if self._solver_model.SolCount == 0:
        raise NoSolutionError()
    attr = "X" if solution_id == 0 else "Xn"
    pyomo_vars, vals = self._get_var_values(vars_to_load, attr, solution_id)
    for pv, val in zip(pyomo_vars, vals):
        pv.set_value(val, skip_validation=True)
    StaleFlagManager.mark_all_as_stale(delayed=True)

def get_primals(
    self, vars_to_load: Optional[Sequence[VarData]] = None, solution_id=0
) -> Mapping[VarData, float]:
    if self._solver_model.SolCount == 0:
        raise NoSolutionError()
    attr = "X" if solution_id == 0 else "Xn"
    pyomo_vars, vals = self._get_var_values(vars_to_load, attr, solution_id)
    return ComponentMap(zip(pyomo_vars, vals))

def get_reduced_costs(
    self, vars_to_load: Optional[Sequence[VarData]] = None
) -> Mapping[VarData, float]:
    if self._solver_model.Status != gurobipy.GRB.OPTIMAL:
        raise NoReducedCostsError()
    if self._solver_model.IsMIP:
        # this will also return True for continuous, nonconvex models
        raise NoReducedCostsError()
    pyomo_vars, vals = self._get_var_values(vars_to_load, "Rc", 0)
    return ComponentMap(zip(pyomo_vars, vals))
